mapper.select:
SELECT c.chat_id, c.stu_id, u.real_name AS student_name, s.student_no, c.question, c.question_type, c.create_time FROM my_ai_chat c LEFT JOIN my_student s ON s.stu_id = c.stu_id LEFT JOIN my_sys_user u ON u.user_id = s.user_id
(c.answer IS NULL OR c.answer = '') AND c.teacher_id = #{teacherId}
ORDER BY c.create_time DESC, c.chat_id DESC

SELECT c.chat_id, c.stu_id, u.real_name AS student_name, s.student_no, c.question, c.question_type, c.create_time, c.answer FROM my_ai_chat c LEFT JOIN my_student s ON s.stu_id = c.stu_id LEFT JOIN my_sys_user u ON u.user_id = s.user_id
c.answer IS NOT NULL AND c.answer != '' AND c.teacher_id = #{teacherId}
ORDER BY c.create_time DESC, c.chat_id DESC

mapper.update:
UPDATE my_ai_chat
answer = #{answer}, teacher_id = #{teacherId}, is_satisfied = 0
WHERE chat_id = #{chatId}
